BEGIN TRANSACTION;
CREATE TABLE v7_alias_policy ("alias_cluster" TEXT,"source_group" TEXT,"names" TEXT,"wiki_ids" TEXT,"exact_original_sprite_set" TEXT,"policy" TEXT,"combined_listing_view_allowed" TEXT,"conflict_fields" TEXT,"runtime_identity_verified" TEXT,"new_visual_review" TEXT,"prior_v6_visual_review" TEXT);
CREATE TABLE v7_field_resolution ("alias_cluster" TEXT,"field" TEXT,"state" TEXT,"recorded_values_json" TEXT,"wiki_evidence_json" TEXT,"usable_listing_value" TEXT,"value_scope" TEXT);
CREATE TABLE v7_listing_membership ("alias_cluster" TEXT,"wiki_id" TEXT,"query_identity" TEXT,"policy" TEXT);
CREATE TABLE v7_pending_visual_review ("source_group" TEXT,"names" TEXT,"image_path" TEXT,"status" TEXT,"required_action" TEXT);
CREATE TABLE v7_preserved_tile_references ("wiki_id" TEXT,"source_group" TEXT,"original_sprite_id" TEXT,"wiki_name" TEXT,"wiki_category" TEXT,"source_container" TEXT,"source_capacity" TEXT,"source_Facing" TEXT,"source_SpriteGridPos" TEXT,"alias_cluster" TEXT);
CREATE TABLE v7_preserved_wiki_properties ("wiki_id" TEXT,"source_group" TEXT,"original_name" TEXT,"wiki_category" TEXT,"wiki_subcategory" TEXT,"wiki_capacity_raw" TEXT,"wiki_size_raw" TEXT,"wiki_encumbrance_raw" TEXT,"wiki_crafting_surface_raw" TEXT,"wiki_bed_quality_raw" TEXT,"wiki_article" TEXT);
CREATE UNIQUE INDEX v7_alias_id ON v7_alias_policy(alias_cluster);
CREATE UNIQUE INDEX v7_field_id ON v7_field_resolution(alias_cluster,field);
CREATE UNIQUE INDEX v7_wiki_id ON v7_listing_membership(wiki_id);
CREATE VIEW v7_queryable_listing_properties AS
      SELECT m.query_identity,p.* FROM v7_listing_membership m
      JOIN v7_preserved_wiki_properties p USING(wiki_id);
COMMIT;
